package com.example.blades360;
import android.content.Context;
import com.wireguard.config.*;
import com.wireguard.crypto.KeyPair;
import okhttp3.*;
import org.json.*;
import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.security.cert.CertificateFactory;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** PIA's documented manual-connection flow. No credentials or private keys are logged. */
final class PiaApi {
 static OkHttpClient http(){return new OkHttpClient.Builder().connectTimeout(12,TimeUnit.SECONDS).readTimeout(20,TimeUnit.SECONDS).callTimeout(35,TimeUnit.SECONDS).followRedirects(false).followSslRedirects(false).build();}
 static String response(OkHttpClient client,Request request)throws Exception{try(Response response=client.newCall(request).execute()){if(!response.isSuccessful()||response.body()==null)throw new IOException("Service request failed");try(InputStream in=response.body().byteStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];for(int n;(n=in.read(bytes))!=-1;){if(out.size()+n>1024*1024)throw new IOException("Response too large");out.write(bytes,0,n);}return out.toString("UTF-8");}}}
 static String login(String username,String password)throws Exception{RequestBody body=new MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart("username",username).addFormDataPart("password",password).build();JSONObject data=new JSONObject(response(http(),new Request.Builder().url("https://www.privateinternetaccess.com/api/client/v2/token").post(body).build()));String token=data.optString("token");if(token.isEmpty()||token.equals("null"))throw new IOException("PIA sign-in failed");return token;}
 static JSONArray regions()throws Exception{String response=response(http(),new Request.Builder().url("https://serverlist.piaservers.net/vpninfo/servers/v6").build());JSONArray all=new JSONObject(response.split("\n",2)[0]).getJSONArray("regions"),us=new JSONArray();for(int i=0;i<all.length();i++){JSONObject region=all.getJSONObject(i);if(region.optString("country").equals("US")&&region.getJSONObject("servers").optJSONArray("wg")!=null)us.put(region);}return us;}
 static JSONObject choose(JSONArray regions,String id)throws Exception{for(int i=0;i<regions.length();i++)if(regions.getJSONObject(i).optString("id").equals(id))return regions.getJSONObject(i);throw new IOException("Selected US region unavailable");}
 static Config connect(Context context,JSONObject region,String token,boolean allApps)throws Exception{JSONArray servers=region.getJSONObject("servers").getJSONArray("wg");KeyPair keys=new KeyPair();Exception last=new IOException("PIA server unavailable");for(int i=0;i<Math.min(3,servers.length());i++)try{JSONObject server=servers.getJSONObject(i);String ip=server.getString("ip"),host=server.getString("cn");KeyStore trust=KeyStore.getInstance(KeyStore.getDefaultType());trust.load(null);try(InputStream in=context.getAssets().open("vpn/pia-ca.crt")){trust.setCertificateEntry("pia",CertificateFactory.getInstance("X.509").generateCertificate(in));}TrustManagerFactory tm=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());tm.init(trust);X509TrustManager manager=(X509TrustManager)tm.getTrustManagers()[0];SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,new TrustManager[]{manager},null);OkHttpClient client=http().newBuilder().sslSocketFactory(ssl.getSocketFactory(),manager).dns(name->{if(!name.equals(host))throw new UnknownHostException();return Collections.singletonList(InetAddress.getByName(ip));}).build();HttpUrl url=new HttpUrl.Builder().scheme("https").host(host).port(1337).addPathSegment("addKey").addQueryParameter("pt",token).addQueryParameter("pubkey",keys.getPublicKey().toBase64()).build();JSONObject data=new JSONObject(response(client,new Request.Builder().url(url).build()));if(!data.optString("status").equals("OK"))throw new IOException("PIA registration failed");if(data.has("peer_key")&&!data.getString("peer_key").equals(keys.getPublicKey().toBase64()))throw new IOException("PIA key mismatch");String address=data.getString("peer_ip");com.wireguard.config.Interface.Builder iface=new com.wireguard.config.Interface.Builder().setKeyPair(keys).parseAddresses(address.contains("/")?address:address+"/32").parseDnsServers(data.getJSONArray("dns_servers").getString(0)).setMtu(1280);if(!allApps)iface.includeApplication(context.getPackageName());Peer peer=new Peer.Builder().parsePublicKey(data.getString("server_key")).parseEndpoint(ip+":"+data.getInt("server_port")).parseAllowedIPs("0.0.0.0/0").setPersistentKeepalive(25).build();return new Config.Builder().setInterface(iface.build()).addPeer(peer).build();}catch(Exception e){last=e;}throw new IOException("Could not register with PIA's WireGuard service");}
}
